const API_BASE_URL = import.meta.env.VITE_API_URL || 'http://localhost:5000/api/admin';

class AdminService {
  private token: string = '';

  setToken(token: string) {
    this.token = token;
  }

  private getHeaders() {
    return {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${this.token}`
    };
  }

  // Authentication
  async login(username: string, password: string): Promise<{ token: string; admin: Admin }> {
    const response = await fetch(`${API_BASE_URL}/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, password })
    });
    return response.json();
  }

  async logout(): Promise<void> {
    await fetch(`${API_BASE_URL}/logout`, {
      method: 'POST',
      headers: this.getHeaders()
    });
  }

  // Dashboard
  async getDashboardData(): Promise<AdminDashboardData> {
    const response = await fetch(`${API_BASE_URL}/dashboard`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  // User Management
  async getUsers(filters?: any): Promise<User[]> {
    const params = new URLSearchParams(filters).toString();
    const response = await fetch(`${API_BASE_URL}/users?${params}`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  async getUserDetails(userId: string): Promise<User> {
    const response = await fetch(`${API_BASE_URL}/users/${userId}`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  async updateUser(userId: string, data: Partial<User>): Promise<void> {
    await fetch(`${API_BASE_URL}/users/${userId}`, {
      method: 'PUT',
      headers: this.getHeaders(),
      body: JSON.stringify(data)
    });
  }

  async blockUser(userId: string, reason: string): Promise<void> {
    await fetch(`${API_BASE_URL}/users/${userId}/block`, {
      method: 'POST',
      headers: this.getHeaders(),
      body: JSON.stringify({ reason })
    });
  }

  async deleteUser(userId: string): Promise<void> {
    await fetch(`${API_BASE_URL}/users/${userId}`, {
      method: 'DELETE',
      headers: this.getHeaders()
    });
  }

  async unblockUser(userId: string): Promise<void> {
    await fetch(`${API_BASE_URL}/users/${userId}/unblock`, {
      method: 'POST',
      headers: this.getHeaders()
    });
  }

